60	@RestController
61	@CrossOrigin(exposedHeaders = "errors, content-type")
62	@RequestMapping("/api")
63	public class OwnerRestControllerV1 implements OwnersApi {
64	
65	    /** Dedicated audit trail for owner-lifecycle side effects. */
66	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
67	
68	    /** Email domains from disposable/throwaway providers, rejected on create. */
69	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
70	        "mailinator.com", "tempmail.com", "guerrillamail.com");
71	
72	    private final ClinicService clinicService;
73	
74	    private final OwnerMapper ownerMapper;
75	
76	    private final PetMapper petMapper;
77	
78	    private final VisitMapper visitMapper;
79	
80	    public OwnerRestControllerV1(ClinicService clinicService,
81	                                 OwnerMapper ownerMapper,
82	                                 PetMapper petMapper,
83	                                 VisitMapper visitMapper) {
84	        this.clinicService = clinicService;
85	        this.ownerMapper = ownerMapper;
86	        this.petMapper = petMapper;
87	        this.visitMapper = visitMapper;
88	    }
89	
90	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
91	    @Override
92	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
93	        Collection<Owner> owners;
94	        if (lastName != null) {
95	            owners = this.clinicService.findOwnerByLastName(lastName);
96	        } else {
97	            owners = this.clinicService.findAllOwners();
98	        }
99	        if (owners.isEmpty()) {
100	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
101	        }
102	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
103	    }
104	
105	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
106	    @Override
107	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
108	        Owner owner = this.clinicService.findOwnerById(ownerId);
109	        if (owner == null) {
110	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
111	        }
112	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
113	    }
114	
115	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
116	    @Override
117	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
118	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
119	        if (normalizedTelephone == null) {
120	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
121	        }
122	        if (isDisposableEmailDomain(ownerFieldsDto.getEmail())) {
123	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
124	        }
125	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
126	        // The owner must supply an address in EITHER form: a non-blank structured
127	        // 'addressLine1' or the flat 'address'. getAddress() prefers the structured
128	        // fields (composing line 1 with an optional line 2) and falls back to the flat
129	        // value; a blank result means neither form was provided. The composed value is
130	        // written back so the persisted flat 'address' stays consistent with it.
131	        String composedAddress = owner.getAddress();
132	        if (composedAddress == null || composedAddress.isBlank()) {
133	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
134	        }
135	        owner.setAddress(composedAddress);
136	        owner.setTelephone(normalizedTelephone);
137	        if (!owner.isPostcodeValidForCity()) {
138	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
139	        }
140	        // The household id is deterministic: it is derived purely from the owner's
141	        // (last name, postcode), so every owner at the same last name and postcode resolves
142	        // to the same value. It is assigned up front, before any duplicate detection, so the
143	        // identity key and the household check below both key off it.
144	        owner.setHouseholdId(householdId(owner.getLastName(), owner.getPostcode()));
145	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
146	        // Consolidated hard-duplicate detection: reject only when the new owner's WHOLE
147	        // identityKey (telephone|email|householdId) equals an existing owner's. With the
148	        // household id now computed up front, two members of one household still differ here
149	        // whenever their telephone or email differs, and so are both allowed.
150	        String identityKey = owner.getIdentityKey();
151	        if (this.clinicService.findAllOwners().stream()
152	            .filter(existing -> !existing.isDeleted())
153	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()))) {
154	            return new ResponseEntity<>(HttpStatus.CONFLICT);
155	        }
156	        // Household duplicate: because the household is keyed on (last name, postcode), any
157	        // existing owner sharing this computed household id is the same household. A second
158	        // such owner is rejected as a household duplicate (409) unless it explicitly declares
159	        // 'sharesHousehold', which now only bypasses this block (the link is no longer created
160	        // here — the id is computed).
161	        List<Owner> householdMembers = findHouseholdMembers(owner.getHouseholdId());
162	        if (!householdMembers.isEmpty() && !sharesHousehold) {
163	            return new ResponseEntity<>(HttpStatus.CONFLICT);
164	        }
165	        if (countOwnersInCity(ownerFieldsDto.getCity()) >= 50) {
166	            return new ResponseEntity<>(HttpStatus.CONFLICT);
167	        }
168	        if (owner.getRegistrationDate() != null && owner.getRegistrationDate().isAfter(LocalDate.now())) {
169	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
170	        }
171	        LocalDate effectiveDate =
172	            owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
173	        LocalDate registrationDate = toBusinessDay(effectiveDate);
174	        long ownersRegisteredToday = countOwnersRegisteredOn(registrationDate);
175	        if (ownersRegisteredToday >= 100) {
176	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
177	        }
178	        boolean bulkSignupWarning = ownersRegisteredToday > 80;
179	        HttpHeaders headers = new HttpHeaders();
180	        owner.setRegistrationDate(registrationDate);
181	        owner.setCustomerCode(customerCode(owner));
182	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
183	        owner.setBulkSignupWarning(bulkSignupWarning);
184	        // The household size (an input to the membership computation) keys off the computed
185	        // household id: this owner plus everyone already sharing it.
186	        owner.setHouseholdSize(householdMembers.size() + 1);
187	        // Soft-match ("possible duplicate"): a declared household member is not a suspected
188	        // duplicate, so only a non-declared create is scored. In practice a non-declared owner
189	        // sharing an existing owner's last name and postcode is already rejected above as a
190	        // household duplicate, so this now only ever confirms the owner is not a duplicate.
191	        Owner possibleDuplicate = sharesHousehold ? null : findPossibleDuplicate(owner);
192	        owner.setPossibleDuplicate(possibleDuplicate != null);
193	        owner.setPossibleDuplicateOf(possibleDuplicate == null ? null : possibleDuplicate.getId());
194	        this.clinicService.saveOwner(owner);
195	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
196	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel(),
197	            owner.getMembershipNumber());
198	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
199	        headers.setLocation(UriComponentsBuilder.newInstance()
200	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
201	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
202	    }
