204	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
205	    @Override
206	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
207	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
208	        if (currentOwner == null) {
209	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
210	        }
211	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
212	        if (normalizedTelephone == null) {
213	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
214	        }
215	        currentOwner.setAddress(ownerFieldsDto.getAddress());
216	        currentOwner.setCity(ownerFieldsDto.getCity());
217	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
218	        currentOwner.setLastName(ownerFieldsDto.getLastName());
219	        currentOwner.setTelephone(normalizedTelephone);
220	        currentOwner.setEmail(ownerFieldsDto.getEmail());
221	        this.clinicService.saveOwner(currentOwner);
222	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
223	    }
