276	
277	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
278	    @Override
279	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
280	        HttpHeaders headers = new HttpHeaders();
281	        Visit visit = visitMapper.toVisit(visitFieldsDto);
282	        Pet pet = new Pet();
283	        pet.setId(petId);
284	        visit.setPet(pet);
285	        this.clinicService.saveVisit(visit);
286	        VisitDto visitDto = visitMapper.toVisitDto(visit);
287	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
288	            .buildAndExpand(visit.getId()).toUri());
289	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
290	    }
291	
292	
293	    /**
294	     * Normalize a telephone number to E.164 form. Spaces, dashes and brackets are
295	     * stripped. When a leading {@code '+'} and country code are present they are kept;
296	     * otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
297	     * is dropped from the national digits. The result must be a {@code '+'} followed
298	     * by 8 to 15 digits, and is returned as {@code +<digits>}; otherwise {@code null}
299	     * is returned to signal a bad request.
300	     */
301	    /**
302	     * Build the customer code for a newly created owner, formatted
303	     * {@code '<REGION>-<HASH8>'} where {@code REGION} is the region derived from the
304	     * owner's postcode (falling back to the city, or {@code 'UNKNOWN'}, via the same
305	     * derivation the locality uses), and {@code HASH8} is the first eight upper-case
306	     * hex characters of the SHA-256 of the owner's normalized telephone concatenated
307	     * with its last name. This identity carries no sequence number.
308	     */
309	    private String customerCode(Owner owner) {
310	        String region = owner.getLocality();
311	        String hash8 = customerCodeHash(owner.getTelephone(), owner.getLastName());
312	        String base = region + "-" + hash8;
313	        java.util.Set<String> existing = this.clinicService.findAllOwners().stream()
314	            .map(Owner::getCustomerCode)
315	            .filter(java.util.Objects::nonNull)
316	            .collect(java.util.stream.Collectors.toSet());
317	        if (!existing.contains(base)) {
318	            return base;
319	        }
320	        int n = 2;
321	        while (existing.contains(base + "-" + n)) {
322	            n++;
323	        }
324	        return base + "-" + n;
325	    }
326	
327	    /**
328	     * Compute the {@code HASH8} portion of a customer code: the first eight upper-case
329	     * hex characters of the SHA-256 digest of {@code telephone + lastName} (each
330	     * treated as empty when {@code null}), already in their normalized forms.
331	     */
332	    private String customerCodeHash(String telephone, String lastName) {
333	        String key = (telephone == null ? "" : telephone) + (lastName == null ? "" : lastName);
334	        try {
335	            byte[] digest = MessageDigest.getInstance("SHA-256")
336	                .digest(key.getBytes(StandardCharsets.UTF_8));
337	            StringBuilder sb = new StringBuilder();
338	            for (int i = 0; i < 4; i++) {
339	                sb.append(String.format("%02X", digest[i]));
340	            }
341	            return sb.toString();
342	        }
343	        catch (NoSuchAlgorithmException e) {
344	            throw new IllegalStateException(e);
345	        }
346	    }
347	
348	    /**
349	     * Count the existing owners whose city matches the given one, compared after
350	     * collapsing whitespace and lower-casing. Used to enforce the per-city capacity
351	     * cap: a city that already holds this many owners is at capacity.
352	     */
353	    private long countOwnersInCity(String city) {
354	        String normalizedCity = normalizeForHousehold(city);
355	        return this.clinicService.findAllOwners().stream()
356	            .filter(existing -> normalizeForHousehold(existing.getCity()).equals(normalizedCity))
357	            .count();
358	    }
359	
360	    /**
361	     * Count the existing owners whose registration date falls on the given day. Used to
362	     * enforce the per-day create limit: once this many owners have been registered today,
363	     * the day is at capacity and further creates are rejected.
364	     */
365	    private long countOwnersRegisteredOn(LocalDate day) {
366	        return this.clinicService.findAllOwners().stream()
367	            .filter(existing -> day.equals(existing.getRegistrationDate()))
368	            .count();
369	    }
370	
371	    /**
372	     * The fixed public holidays that the business-day roll skips. A registration date
373	     * landing on one of these is treated like a weekend and advanced to the next
374	     * non-holiday business day.
375	     */
376	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
377	        LocalDate.parse("2026-01-01"),
378	        LocalDate.parse("2026-01-26"),
379	        LocalDate.parse("2026-04-25"),
380	        LocalDate.parse("2026-12-25"),
381	        LocalDate.parse("2026-12-28"));
382	
383	    /**
384	     * Roll a registration date forward to the next business day: a date falling on a
385	     * Saturday, Sunday or listed public holiday is advanced one day at a time until it
386	     * lands on a non-holiday weekday, while a plain weekday is returned unchanged.
387	     */
388	    private LocalDate toBusinessDay(LocalDate date) {
389	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
390	            date = date.plusDays(1);
391	        }
392	        return date;
393	    }
394	
395	    private static boolean isWeekend(LocalDate date) {
396	        DayOfWeek dayOfWeek = date.getDayOfWeek();
397	        return dayOfWeek == DayOfWeek.SATURDAY || dayOfWeek == DayOfWeek.SUNDAY;
398	    }
399	
400	    /**
401	     * Find the existing owners that already belong to the same household as the given
402	     * computed household id. Because the household id is derived deterministically from
403	     * the owner's (last name, postcode), this is exactly the set of other owners sharing
404	     * that last name and postcode.
405	     */
406	    private List<Owner> findHouseholdMembers(String householdId) {
407	        if (householdId == null) {
408	            return List.of();
409	        }
410	        return this.clinicService.findAllOwners().stream()
411	            .filter(existing -> !existing.isDeleted())
412	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
413	            .toList();
414	    }
415	
416	    /**
417	     * Find an existing owner that this new owner softly duplicates: one sharing the same
418	     * last name (compared case-insensitively after whitespace normalization) and the same
419	     * postcode, but with a different telephone. Returns the lowest-id such owner, or
420	     * {@code null} when the new owner has no postcode or no soft match exists. Owners
421	     * whose telephone equals the new owner's are excluded, as those are governed by the
422	     * hard-duplicate (identityKey) check rather than this soft match.
423	     */
424	    private Owner findPossibleDuplicate(Owner owner) {
425	        String postcode = owner.getPostcode();
426	        if (postcode == null) {
427	            return null;
428	        }
429	        String normalizedLastName = normalizeForHousehold(owner.getLastName());
430	        String telephone = owner.getTelephone();
431	        return this.clinicService.findAllOwners().stream()
432	            .filter(existing -> !existing.isDeleted())
433	            .filter(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
434	                && postcode.equals(existing.getPostcode())
435	                && !java.util.Objects.equals(telephone, existing.getTelephone()))
436	            .min(java.util.Comparator.comparing(Owner::getId))
437	            .orElse(null);
438	    }
439	
440	    /**
441	     * Count the existing owners that already share both the given first and last
442	     * name, compared case-insensitively. Used to populate an owner's namesake count
443	     * at creation time, reflecting how many owners with the same name existed before
444	     * this one was created.
445	     */
446	    private int countNamesakes(String firstName, String lastName) {
447	        String normalizedFirstName = normalizeName(firstName);
448	        String normalizedLastName = normalizeName(lastName);
449	        return (int) this.clinicService.findAllOwners().stream()
450	            .filter(existing -> normalizeName(existing.getFirstName()).equals(normalizedFirstName)
451	                && normalizeName(existing.getLastName()).equals(normalizedLastName))
452	            .count();
453	    }
454	
455	    private String normalizeName(String value) {
456	        return value == null ? "" : value.toLowerCase(Locale.ROOT);
457	    }
458	
459	    /**
460	     * Build the deterministic identifier shared by all owners of one household: the first
461	     * 12 hex characters of the SHA-256 digest of {@code normalizedLastName + '|' + postcode}.
462	     * Because it depends only on the (last name, postcode) pair, every owner at the same last
463	     * name and postcode resolves to the same value regardless of creation order.
464	     */
465	    private String householdId(String lastName, String postcode) {
466	        String key = normalizeForHousehold(lastName) + "|" + (postcode == null ? "" : postcode);
467	        try {
468	            byte[] digest = MessageDigest.getInstance("SHA-256")
469	                .digest(key.getBytes(StandardCharsets.UTF_8));
470	            StringBuilder sb = new StringBuilder();
471	            for (int i = 0; i < 6; i++) {
472	                sb.append(String.format("%02x", digest[i]));
473	            }
474	            return sb.toString();
475	        }
476	        catch (NoSuchAlgorithmException e) {
477	            throw new IllegalStateException(e);
478	        }
479	    }
480	
481	    private String normalizeForHousehold(String value) {
482	        if (value == null) {
483	            return "";
484	        }
485	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
486	    }
487	
488	    /** True when the email's domain is on the disposable-provider blocklist. */
489	    private boolean isDisposableEmailDomain(String email) {
490	        if (email == null) {
491	            return false;
492	        }
493	        int at = email.lastIndexOf('@');
494	        if (at < 0 || at == email.length() - 1) {
495	            return false;
496	        }
497	        String domain = email.substring(at + 1).trim().toLowerCase(Locale.ROOT);
498	        return DISPOSABLE_EMAIL_DOMAINS.contains(domain);
499	    }
500	
501	    private String normalizeTelephone(String telephone) {
502	        if (telephone == null) {
503	            return null;
504	        }
505	        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
506	        String digits;
507	        if (cleaned.startsWith("+")) {
508	            digits = cleaned.substring(1);
509	        } else {
510	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
511	            digits = "61" + national;
512	        }
513	        if (!digits.matches("[0-9]{8,15}")) {
514	            return null;
515	        }
516	        if (!hasValidNationalLength(digits)) {
517	            return null;
518	        }
519	        return "+" + digits;
520	    }
521	
522	    /**
523	     * Validate the national-number length of an E.164 number (the digits, without the
524	     * leading {@code '+'}) against its country code. Australia ({@code '+61'}) requires
525	     * exactly 9 national digits and North America ({@code '+1'}) exactly 10; country
526	     * codes without a known rule are accepted as-is.
527	     */
528	    private boolean hasValidNationalLength(String digits) {
529	        if (digits.startsWith("61")) {
530	            return digits.length() - 2 == 9;
531	        }
532	        if (digits.startsWith("1")) {
533	            return digits.length() - 1 == 10;
534	        }
535	        return true;
536	    }
537	
538	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
539	    @Override
540	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
541	        Owner owner = this.clinicService.findOwnerById(ownerId);
542	        if (owner != null) {
543	            Pet pet = owner.getPet(petId);
544	            if (pet != null) {
545	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
546	            }
547	        }
548	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
549	    }
550	}
